import { cc, type SinwanComponent } from "sinwan/component";
import { ChevronLeft, ChevronRight } from "lucide";

import { Icon } from "@/lib/icons";
import { cn } from "@/lib/utils";
import { Button, type ButtonProps } from "@/components/ui/button";
import {
  useCarousel,
  useCarouselRoot,
  useCarouselSwipe,
  type CarouselProps,
} from "./useCarousel";

export const Carousel: SinwanComponent<CarouselProps> = cc((props) => {
  const root = useCarouselRoot(props);

  return (
    <div
      data-slot="carousel"
      role="region"
      aria-roledescription="carousel"
      class={cn("relative", root.class)}
      onkeydown={(event: KeyboardEvent) => {
        if (event.key === "ArrowLeft") {
          event.preventDefault();
          root.scrollPrev();
        } else if (event.key === "ArrowRight") {
          event.preventDefault();
          root.scrollNext();
        }
      }}
    >
      {root.children}
    </div>
  );
});

export type CarouselContentProps = JSX.IntrinsicElements["div"];

export const CarouselContent: SinwanComponent<CarouselContentProps> = cc(
  ({ class: className, ...props }) => {
    const swipe = useCarouselSwipe();

    return (
      <div
        class={cn(
          "overflow-hidden touch-manipulation select-none",
          swipe.orientation === "horizontal" ? "touch-pan-y" : "touch-pan-x",
        )}
        data-slot="carousel-content"
        data-dragging={swipe.isDragging.value ? "" : undefined}
        onpointerdown={swipe.onPointerDown}
      >
        <div
          class={cn(
            "flex ease-out",
            swipe.isDragging.value
              ? "transition-none"
              : "transition-transform duration-300",
            swipe.orientation === "horizontal" ? "-ml-4" : "-mt-4 flex-col",
            className,
          )}
          style={
            swipe.orientation === "horizontal"
              ? { transform: `translateX(${swipe.trackTransform()})` }
              : { transform: `translateY(${swipe.trackTransform()})` }
          }
          {...props}
        />
      </div>
    );
  },
);

export type CarouselItemProps = JSX.IntrinsicElements["div"];

export const CarouselItem: SinwanComponent<CarouselItemProps> = cc(
  ({ class: className, ...props }) => {
    const { orientation, registerSlide } = useCarousel();
    registerSlide();

    return (
      <div
        role="group"
        aria-roledescription="slide"
        data-slot="carousel-item"
        class={cn(
          "min-w-0 shrink-0 grow-0 basis-full",
          orientation === "horizontal" ? "pl-4" : "pt-4",
          className,
        )}
        {...props}
      />
    );
  },
);

export type CarouselControlProps = ButtonProps;

export const CarouselPrevious: SinwanComponent<CarouselControlProps> = cc(
  ({
    class: className,
    variant = "outline",
    size = "icon-sm",
    ...props
  }) => {
    const { orientation, scrollPrev, canScrollPrev } = useCarousel();

    return (
      <Button
        data-slot="carousel-previous"
        variant={variant}
        size={size}
        class={cn(
          "absolute touch-manipulation rounded-full data-disabled:pointer-events-none data-disabled:opacity-50",
          orientation === "horizontal"
            ? "inset-y-0 -left-12 my-auto"
            : "-top-12 left-1/2 -translate-x-1/2 rotate-90",
          className,
        )}
        data-disabled={!canScrollPrev.value ? "" : undefined}
        onclick={() => {
          if (canScrollPrev.value) scrollPrev();
        }}
        {...(props as ButtonProps)}
      >
        <Icon icon={ChevronLeft} />
        <span class="sr-only">Previous slide</span>
      </Button>
    );
  },
);

export const CarouselNext: SinwanComponent<CarouselControlProps> = cc(
  ({
    class: className,
    variant = "outline",
    size = "icon-sm",
    ...props
  }) => {
    const { orientation, scrollNext, canScrollNext } = useCarousel();

    return (
      <Button
        data-slot="carousel-next"
        variant={variant}
        size={size}
        class={cn(
          "absolute touch-manipulation rounded-full data-disabled:pointer-events-none data-disabled:opacity-50",
          orientation === "horizontal"
            ? "inset-y-0 -right-12 my-auto"
            : "-bottom-12 left-1/2 -translate-x-1/2 rotate-90",
          className,
        )}
        data-disabled={!canScrollNext.value ? "" : undefined}
        onclick={() => {
          if (canScrollNext.value) scrollNext();
        }}
        {...(props as ButtonProps)}
      >
        <Icon icon={ChevronRight} />
        <span class="sr-only">Next slide</span>
      </Button>
    );
  },
);

export {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
  type CarouselContentProps,
  type CarouselControlProps,
  type CarouselItemProps,
} from "./carousel";
export {
  useCarousel,
  useCarouselRoot,
  useCarouselSwipe,
  type CarouselApi,
  type CarouselContext,
  type CarouselProps,
  type CarouselRootReturn,
  type CarouselSwipeReturn,
} from "./useCarousel";

import {
  inject,
  onUnmounted,
  provide,
  type InjectionKey,
  type SinwanNode,
} from "sinwan/component";
import { computed, signal, type Computed, type Signal } from "sinwan/reactivity";

export type CarouselApi = {
  scrollPrev: () => void;
  scrollNext: () => void;
  scrollTo: (index: number) => void;
  index: Signal<number>;
  canScrollPrev: Computed<boolean>;
  canScrollNext: Computed<boolean>;
};

export type CarouselContext = {
  orientation: "horizontal" | "vertical";
  index: Signal<number>;
  slideCount: Signal<number>;
  registerSlide: () => number;
  scrollPrev: () => void;
  scrollNext: () => void;
  scrollTo: (index: number) => void;
  canScrollPrev: Computed<boolean>;
  canScrollNext: Computed<boolean>;
};

export type CarouselProps = {
  orientation?: "horizontal" | "vertical";
  class?: string;
  children?: SinwanNode;
  setApi?: (api: CarouselApi) => void;
  opts?: { startIndex?: number; loop?: boolean };
};

export type CarouselRootReturn = {
  orientation: "horizontal" | "vertical";
  class: string | undefined;
  children: SinwanNode | undefined;
  scrollPrev: () => void;
  scrollNext: () => void;
  api: CarouselApi;
};

export type CarouselSwipeReturn = {
  orientation: "horizontal" | "vertical";
  index: Signal<number>;
  dragOffset: Signal<number>;
  isDragging: Signal<boolean>;
  onPointerDown: (event: PointerEvent) => void;
  trackTransform: () => string;
};

const CarouselKey: InjectionKey<CarouselContext> = Symbol("sinwan-ui.carousel");

const SWIPE_LOCK_PX = 8;
const SWIPE_COMMIT_PX = 48;
const SWIPE_EDGE_RESIST = 0.35;

function pointerClientPoint(
  event: Event,
): { clientX: number; clientY: number } | null {
  if (!("clientX" in event) || !("clientY" in event)) return null;
  const point = event as { clientX: number; clientY: number };
  return { clientX: point.clientX, clientY: point.clientY };
}

function swipeAxis(
  point: { clientX: number; clientY: number },
  orientation: "horizontal" | "vertical",
): { main: number; cross: number } {
  return orientation === "horizontal"
    ? { main: point.clientX, cross: point.clientY }
    : { main: point.clientY, cross: point.clientX };
}

function resistedSwipeDelta(
  raw: number,
  canScrollPrev: boolean,
  canScrollNext: boolean,
): number {
  if (raw > 0 && !canScrollPrev) return raw * SWIPE_EDGE_RESIST;
  if (raw < 0 && !canScrollNext) return raw * SWIPE_EDGE_RESIST;
  return raw;
}

/**
 * Carousel selection, navigation, and context without default styles.
 * Call from a root carousel component; children use `useCarousel()`.
 */
export function useCarouselRoot(props: CarouselProps): CarouselRootReturn {
  const orientation = props.orientation ?? "horizontal";
  const index = signal(props.opts?.startIndex ?? 0);
  const slideCount = signal(0);
  const loop = props.opts?.loop ?? false;
  let slideSeq = 0;

  const canScrollPrev = computed(() => loop || index.value > 0);
  const canScrollNext = computed(
    () => loop || index.value < slideCount.value - 1,
  );

  const scrollTo = (next: number) => {
    const count = slideCount.value;
    if (count <= 0) return;
    if (loop) {
      index.value = ((next % count) + count) % count;
      return;
    }
    index.value = Math.min(count - 1, Math.max(0, next));
  };

  const scrollPrev = () => scrollTo(index.value - 1);
  const scrollNext = () => scrollTo(index.value + 1);

  const registerSlide = () => {
    const current = slideSeq;
    slideSeq += 1;
    slideCount.value = slideSeq;
    return current;
  };

  const api: CarouselApi = {
    scrollPrev,
    scrollNext,
    scrollTo,
    index,
    canScrollPrev,
    canScrollNext,
  };
  props.setApi?.(api);

  provide(CarouselKey, {
    orientation,
    index,
    slideCount,
    registerSlide,
    scrollPrev,
    scrollNext,
    scrollTo,
    canScrollPrev,
    canScrollNext,
  });

  void computed(() => index.value);

  return {
    orientation,
    class: props.class,
    children: props.children,
    scrollPrev,
    scrollNext,
    api,
  };
}

/**
 * Inject the carousel context. Must be used under a root that called
 * `useCarouselRoot` (or the default `<Carousel />`).
 */
export function useCarousel(): CarouselContext {
  const context = inject(CarouselKey);
  if (!context) {
    throw new Error("useCarousel must be used within a <Carousel />");
  }
  return context;
}

/**
 * Pointer swipe / drag behavior for a carousel track. Style the viewport
 * and track yourself; this owns drag offset and slide commit.
 */
export function useCarouselSwipe(): CarouselSwipeReturn {
  const {
    orientation,
    index,
    scrollPrev,
    scrollNext,
    canScrollPrev,
    canScrollNext,
  } = useCarousel();
  const dragOffset = signal(0);
  const isDragging = signal(false);
  let stopSwipe: (() => void) | null = null;

  const onPointerDown = (event: PointerEvent) => {
    if ("button" in event && event.button !== 0) return;
    const startPoint = pointerClientPoint(event);
    if (!startPoint) return;
    const start = swipeAxis(startPoint, orientation);
    let locked: boolean | null = null;
    let rawDelta = 0;

    const finish = (commit: boolean) => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onCancel);
      if (commit && locked && Math.abs(rawDelta) >= SWIPE_COMMIT_PX) {
        if (rawDelta < 0) {
          if (canScrollNext.value) scrollNext();
        } else if (canScrollPrev.value) {
          scrollPrev();
        }
      }
      dragOffset.value = 0;
      isDragging.value = false;
      stopSwipe = null;
    };

    const onMove = (moveEvent: Event) => {
      const point = pointerClientPoint(moveEvent);
      if (!point) return;
      const pos = swipeAxis(point, orientation);
      const dMain = pos.main - start.main;
      const dCross = pos.cross - start.cross;
      if (locked === null) {
        if (
          Math.abs(dMain) < SWIPE_LOCK_PX &&
          Math.abs(dCross) < SWIPE_LOCK_PX
        ) {
          return;
        }
        locked = Math.abs(dMain) >= Math.abs(dCross);
        if (!locked) return;
        isDragging.value = true;
      }
      if (!locked) return;
      if (moveEvent.cancelable) moveEvent.preventDefault();
      rawDelta = dMain;
      dragOffset.value = resistedSwipeDelta(
        dMain,
        canScrollPrev.value,
        canScrollNext.value,
      );
    };

    const onUp = () => finish(true);
    const onCancel = () => finish(false);

    stopSwipe?.();
    stopSwipe = () => finish(false);
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onCancel);
  };

  onUnmounted(() => {
    stopSwipe?.();
  });

  const trackTransform = () => {
    const base = `${-index.value * 100}%`;
    const offset = dragOffset.value;
    if (offset === 0) return base;
    return `calc(${base} + ${offset}px)`;
  };

  return {
    orientation,
    index,
    dragOffset,
    isDragging,
    onPointerDown,
    trackTransform,
  };
}
